Three modules of the CodeDev API:

@Module({ providers: [UserService, UserRepository], exports: [UserService] })
export class UserModule {}

@Module({
  imports: [UserModule],
  providers: [CourseService, CourseRepository],
  exports: [CourseService],
})
export class CourseModule {}

@Module({ imports: [CourseModule], providers: [EnrollmentService, EnrollmentRepository] })
export class EnrollmentModule {}

@Injectable()
export class EnrollmentService {
  constructor(
    private readonly courses: CourseService,
    private readonly users: UserService,
  ) {}
}

Statement: "The application starts, because EnrollmentModule imports CourseModule, CourseModule imports UserModule, and so UserService is available to EnrollmentService."

CourseService caches course outlines in memory for 10 minutes; CourseController calls courseService.invalidate(courseId) after an admin edits a course with PATCH /courses/:id. EnrollmentModule failed at startup because CourseService was missing, and this fix was merged:

// src/enrollments/enrollment.module.ts
 @Module({
   controllers: [EnrollmentController],
-  providers: [EnrollmentService, EnrollmentRepository],
+  providers: [EnrollmentService, EnrollmentRepository, CourseService, CourseRepository],
 })
 export class EnrollmentModule {}

// src/courses/course.module.ts (unchanged)
@Module({
  controllers: [CourseController],
  providers: [CourseService, CourseRepository],
  exports: [CourseService],
})
export class CourseModule {}

Statement: "After this fix, when an admin marks two lessons of course 42 as previews with PATCH /courses/42, the price quote from EnrollmentService uses the new outline right away."

ProgressService and its controller:

@Injectable()
export class ProgressService {
  private currentUserId?: string;
  setUser(userId: string) { this.currentUserId = userId; }

  async complete(lessonId: string) {
    await this.courses.getOutlineForLesson(lessonId);          // about 25 ms
    await this.progress.insert(this.currentUserId!, lessonId);
  }
}

@Post(":id/complete")
async complete(@Param("id") lessonId: string, @Req() req: AuthenticatedRequest) {
  this.progressService.setUser(req.user.id);
  return this.progressService.complete(lessonId);
}

